// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/YUG.sol";

contract YUGInfiniteMintTest is Test {
    YUG public token;
    address public owner;

    uint256 public constant MINT_AMOUNT = 1e18; // 1 token
    uint256 public constant LARGE_MINT_AMOUNT = 10e18; // 10 tokens

    function setUp() public {
        // Use a fork of BSC mainnet
        vm.createSelectFork("https://bsc-dataseed.binance.org/");

        owner = address(this);

        // Deploy the token contract - owner is automatically excluded from fees
        token = new YUG();

        // Verify setup
        assertEq(token.owner(), owner, "Test contract should be token owner");
    }

    function testOwnerCanMintUnlimitedTokens() public {
        // Store initial values
        uint256 initialSupply = token.totalSupply();
        uint256 initialOwnerBalance = token.balanceOf(owner);

        // First mint
        token.mint(owner, MINT_AMOUNT);

        // Verify first mint results
        uint256 newSupply = token.totalSupply();
        uint256 newOwnerBalance = token.balanceOf(owner);

        assertEq(newSupply, initialSupply + MINT_AMOUNT, "Total supply should increase by mint amount");
        assertEq(newOwnerBalance, initialOwnerBalance + MINT_AMOUNT, "Owner should receive entire mint amount");

        // Store current values for next test
        uint256 currentSupply = newSupply;
        uint256 currentOwnerBalance = newOwnerBalance;

        // Second, larger mint
        token.mint(owner, LARGE_MINT_AMOUNT);

        // Verify second mint results
        newSupply = token.totalSupply();
        newOwnerBalance = token.balanceOf(owner);

        assertEq(newSupply, currentSupply + LARGE_MINT_AMOUNT, "Total supply should increase by second mint amount");
        assertEq(newOwnerBalance, currentOwnerBalance + LARGE_MINT_AMOUNT, "Owner should accumulate minted tokens");
    }
}
